package com.ajay.amusezone.service;
import com.ajay.amusezone.dto.PaymentRequest; import com.ajay.amusezone.entity.*; import com.ajay.amusezone.repository.*; import org.springframework.stereotype.Service;
@Service public class PaymentService { private final PaymentRepository payments; private final BookingRepository bookings; public PaymentService(PaymentRepository p,BookingRepository b){payments=p;bookings=b;} public Payment pay(PaymentRequest r){Booking b=bookings.findById(r.bookingId()).orElseThrow(()->new RuntimeException("Booking not found")); if(Math.abs(r.amount()-b.getTotalAmount())>0.01) throw new RuntimeException("Payment amount does not match booking total"); Payment p=new Payment();p.setBooking(b);p.setAmount(r.amount());p.setMethod(r.method());p.setStatus("SUCCESS");return payments.save(p);} public Payment getByBooking(Long id){return payments.findByBookingId(id).orElseThrow(()->new RuntimeException("Payment not found"));}}
